function pick() {
  const list = (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || 'it']).map((l) => String(l).toLowerCase());
  for (const l of list) {
    const base = l.split('-')[0];
    if (T[base]) return base;
  }
  return 'it';
}
export const LANG = pick();
const D = T[LANG];

export function t(key, vars) {
  let s = D[key];
  if (s === undefined) s = T.it[key];
  if (s === undefined) return key;
  if (typeof s === 'function') s = s(vars || {});
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined && vars[k] !== null ? String(vars[k]) : m));
  return s;
}
